"""SSTV pipeline test: decodes a PD120 picture generated by the pySSTV encoder if it is available."""
import os, sys, time, tempfile, shutil
sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
if os.environ.get("PYSSTV_PATH"):                         # a pySSTV source folder, if it is not installed
    sys.path.insert(0, os.environ["PYSSTV_PATH"])
from PIL import Image, ImageDraw
from pysstv.color import PD120
import config as C, weather, space as S
tmp = tempfile.mkdtemp(); os.environ["DATA_DIR"] = tmp
cfg = C.Config(); ev = []
d = weather.Decoder(cfg, lambda t, **k: ev.append((t, k)), S.Space(cfg))
im = Image.new("RGB", (640, 496), (30, 60, 120)); dr = ImageDraw.Draw(im); dr.rectangle((40, 40, 300, 200), fill=(220, 40, 40)); dr.ellipse((350, 100, 600, 400), fill=(240, 220, 40))
name = "20261102-101500_145.8000MHz_nfm_iss.wav"
PD120(im, 48000, 16).write_wav(cfg.path_for("recordings", name))
did = d.submit(name)
for _ in range(200):
    time.sleep(0.2)
    if any(t == "decode_done" for t, _k in ev): break
r = [x for x in d.list() if x["id"] == did][0]
print("ok", r["ok"], [i["title"] for i in r["images"]], r.get("report"))
assert r["ok"] and r["report"] and os.path.getsize(d.file_path(did, "report.pdf")) > 1000
# a recording with no picture gives a plain-English failure
open(cfg.path_for("recordings", "silence.wav"), "wb").write(open(cfg.path_for("recordings", name), "rb").read()[:20000])
try:
    d.submit("silence.wav"); time.sleep(2)
    print([x.get("error", "")[:60] for x in d.list() if x["id"] == "silence"])
except Exception as e:
    print("note:", e)
print("PASS")
